const $=s=>document.querySelector(s), key='maju-jaya-grosir.v1';
const empty=()=>({version:1,customers:[],debts:[],payments:[],orders:[]});
const savedDateRanges={};
let transactionFrom='',transactionTo='';
let db=empty(), page='dashboard', query='', filter='all';
const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const date=d=>new Date(d+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const customer=id=>db.customers.find(c=>c.id===id);
const paid=id=>db.payments.filter(p=>p.debt_id===id).reduce((s,p)=>s+p.amount,0);
const balance=d=>d.amount-paid(d.id);
const status=d=>balance(d)<=0?'paid':d.due_date<today()?'late':'open';
const statusLabel={paid:'Lunas',late:'Terlambat',open:'Belum lunas'};
const outstanding=id=>db.debts.filter(d=>d.customer_id===id).reduce((n,d)=>n+balance(d),0);
const terms=c=>c.payment_type==='cash'?'Bayar di tempat':c.term_days?`Tempo ${c.term_days} hari`:'Belum diatur';
function maturity(id){const open=db.debts.filter(d=>d.customer_id===id&&balance(d)>0).sort((a,b)=>a.due_date.localeCompare(b.due_date));const due=open[0]?.due_date;return {date:due,amount:open.filter(d=>d.due_date===due).reduce((n,d)=>n+balance(d),0)}}
function dueDate(day,days){const d=new Date(day+'T00:00:00');d.setDate(d.getDate()+Number(days||0));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function transactionSummary(id,from=transactionFrom,to=transactionTo){const transactions=db.debts.filter(d=>d.customer_id===id&&(!from||d.date>=from)&&(!to||d.date<=to));return {count:transactions.length,total:transactions.reduce((sum,d)=>sum+d.amount,0)}}
let rangeMonth=today().slice(0,7),rangeStart='',rangeEnd='',datePreset='all';
function recentMonths(months,end=today()){const d=new Date(end+'T00:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()-months);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return dueDate(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,1)}
function customerDates(){return `<div class="customer-dates"><div class="range-container"><button id="range-toggle" aria-expanded="false" aria-controls="range-picker">▦ ${transactionFrom?date(transactionFrom)+' – '+date(transactionTo):'Pilih rentang tanggal'}</button><div id="range-picker" hidden></div></div><div class="date-shortcuts"><button data-period="1" class="${datePreset==='1'?'primary':''}">1 bulan</button><button data-period="2" class="${datePreset==='2'?'primary':''}">2 bulan</button><button data-period="all" class="${datePreset==='all'?'primary':''}">All data</button></div><p>${page==='payments'?'Riwayat berdasarkan tanggal pembayaran.':'Total transaksi berdasarkan tanggal transaksi; saldo utang tetap seluruh periode.'}</p></div>`}
function drawRange(){const [year,month]=rangeMonth.split('-').map(Number),first=new Date(year,month-1,1),count=new Date(year,month,0).getDate();$('#range-picker').innerHTML=`<div class="calendar-head"><button id="month-prev" aria-label="Bulan sebelumnya">‹</button><b>${first.toLocaleDateString('id-ID',{month:'long',year:'numeric'})}</b><button id="month-next" aria-label="Bulan berikutnya">›</button></div><p>${rangeStart?(rangeEnd?date(rangeStart)+' – '+date(rangeEnd):'Mulai '+date(rangeStart)+'. Pilih tanggal akhir.'):'Klik tanggal awal, lalu tanggal akhir.'}</p><div class="calendar-grid">${['Min','Sen','Sel','Rab','Kam','Jum','Sab'].map(x=>`<small>${x}</small>`).join('')}${'<span></span>'.repeat(first.getDay())}${Array.from({length:count},(_,i)=>{const day=rangeMonth+'-'+String(i+1).padStart(2,'0');return `<button data-day="${day}" aria-label="${date(day)}" class="${day===rangeStart||day===rangeEnd?'selected':rangeStart&&rangeEnd&&day>rangeStart&&day<rangeEnd?'between':''}">${i+1}</button>`}).join('')}</div><div class="calendar-footer"><button id="range-cancel">Batal</button><button id="range-apply" class="primary" ${!rangeStart||!rangeEnd?'disabled':''}>Terapkan</button></div>`;
const move=n=>{rangeMonth=dueDate(rangeMonth+'-01',n<0?-1:32).slice(0,7);drawRange()};$('#month-prev').onclick=()=>move(-1);$('#month-next').onclick=()=>move(1);document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const day=b.dataset.day;if(!rangeStart||rangeEnd){rangeStart=day;rangeEnd=''}else{rangeEnd=day;if(rangeEnd<rangeStart)[rangeStart,rangeEnd]=[rangeEnd,rangeStart]}drawRange()});$('#range-cancel').onclick=()=>{$('#range-picker').hidden=true;$('#range-toggle').setAttribute('aria-expanded','false')};$('#range-apply').onclick=()=>{if(!rangeStart||!rangeEnd)return;transactionFrom=rangeStart;transactionTo=rangeEnd;datePreset='custom';render()}}
function bindCustomerDates(){if(page!=='customers'&&page!=='payments')return;$('#range-toggle').onclick=()=>{const opening=$('#range-picker').hidden;$('#range-picker').hidden=!opening;$('#range-toggle').setAttribute('aria-expanded',String(opening));if(opening){rangeStart=transactionFrom;rangeEnd=transactionTo;rangeMonth=(transactionFrom||today()).slice(0,7);drawRange()}};document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{datePreset=b.dataset.period;transactionFrom=datePreset==='all'?'':recentMonths(Number(datePreset));transactionTo=datePreset==='all'?'':today();render()})}
async function save(next){db=await cloudStore.save(db,next)}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function person(c){return `<div class="person"><span class="initial">${esc(c.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase())}</span><div><b>${esc(c.name)}</b><small>${esc(c.phone||'Tanpa nomor telepon')}</small></div></div>`}
function blank(label,sub,action,button){return `<div class="empty"><strong>${label}</strong>${sub?`<p>${sub}</p>`:''}${action?`<button data-action="${action}" class="primary">＋ ${button}</button>`:''}</div>`}
function debtDistribution(){
 const ranked=db.customers.map(c=>({name:c.name,total:outstanding(c.id)})).filter(c=>c.total>0).sort((a,b)=>b.total-a.total);
 const total=ranked.reduce((n,c)=>n+c.total,0),slices=ranked.slice(0,5);
 if(ranked.length>5)slices.push({name:'Langganan lainnya',total:ranked.slice(5).reduce((n,c)=>n+c.total,0)});
 return {total,slices};
}
function debtChart(){const {total,slices}=debtDistribution(),colors=['#e8bb52','#a97b28','#f6dfa0','#c69a43','#806026','#d7c39a'];let offset=0;
 const arcs=slices.map((c,i)=>{const percent=c.total/total*100,label=c.name+' · '+rupiah(c.total)+' · '+new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(percent)+'%',start=offset;offset+=percent;return `<circle class="donut-segment" cx="110" cy="110" r="76" fill="none" stroke="${colors[i]}" stroke-width="38" pathLength="100" stroke-dasharray="${percent} ${100-percent}" stroke-dashoffset="${-start}" transform="rotate(-90 110 110)" tabindex="0" role="button" aria-label="${esc(label)}" data-chart-info="${esc(label)}"><title>${esc(label)}</title></circle>`}).join('');
 return `<section class="panel debt-chart-panel"><div class="panel-head"><h2>Komposisi piutang aktif</h2></div>${total?`<div class="simple-chart"><svg viewBox="0 0 220 220" aria-label="Persentase piutang aktif per langganan">${arcs}</svg><div id="chart-tooltip" class="chart-tooltip" role="status" hidden></div></div>`:'<div class="empty"><strong>Belum ada piutang aktif</strong></div>'}</section>`;
}
function bindDebtChart(){document.querySelectorAll('[data-chart-info]').forEach(segment=>{const show=()=>{const tip=$('#chart-tooltip');tip.textContent=segment.dataset.chartInfo;tip.hidden=false};const hide=()=>{$('#chart-tooltip').hidden=true};segment.onmouseenter=show;segment.onmouseleave=hide;segment.onfocus=show;segment.onblur=hide;segment.onclick=show;segment.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}if(e.key==='Escape')hide()}})}
function render(){const labels={dashboard:['Ringkasan usaha'],orders:['Order'],customers:['Data langganan'],debts:['Buku piutang'],payments:['Riwayat pembayaran']};$('#title').textContent=labels[page][0];$('#crumb').textContent=labels[page][0];$('#add').hidden=false;$('#add').textContent=page==='orders'?'＋ Tambah pengiriman':page==='customers'?'＋ Tambah langganan':page==='payments'?'＋ Catat pembayaran':'＋ Catat utang';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));let html='';
if(page==='orders'){renderOrders();return}
if(page==='dashboard'){const total=db.debts.reduce((s,d)=>s+balance(d),0),late=db.debts.filter(d=>status(d)==='late'),monthly=db.payments.filter(p=>p.date.slice(0,7)===today().slice(0,7)).reduce((s,p)=>s+p.amount,0),billed=db.debts.reduce((s,d)=>s+d.amount,0),received=db.payments.reduce((s,p)=>s+p.amount,0),percent=billed?Math.round(received/billed*100):0;html=`<div class="cards"><div class="card featured"><div class="card-label">Total piutang aktif <span>↗</span></div><div class="card-value">${rupiah(total)}</div><div class="card-sub">${db.debts.filter(d=>balance(d)>0).length} tagihan belum lunas</div></div><div class="card"><div class="card-label">Pembayaran bulan ini <span>↙</span></div><div class="card-value">${rupiah(monthly)}</div><div class="card-sub">Cicilan dan pelunasan diterima</div></div><div class="card"><div class="card-label">Lewat jatuh tempo <span>◷</span></div><div class="card-value">${rupiah(late.reduce((s,d)=>s+balance(d),0))}</div><div class="card-sub">${late.length} tagihan perlu ditindaklanjuti</div></div><div class="card"><div class="card-label">Total pembeli <span>♧</span></div><div class="card-value">${db.customers.length}<span style="font-size:12px;letter-spacing:0;font-weight:400;color:#8b978e"> pembeli</span></div><div class="card-sub">${new Set(db.debts.filter(d=>balance(d)>0).map(d=>d.customer_id)).size} pembeli memiliki utang</div></div></div><div class="summary-charts"><div class="payment-summary"><div class="panel"><div class="panel-head"><div><h2>Perjalanan pembayaran</h2><p>Proporsi pembayaran dari seluruh piutang tercatat</p></div><span>↗</span></div><div class="health"><div class="health-top"><strong>${percent}<span style="font-size:18px">%</span></strong><span class="tag">${billed?'Sudah terbayar':'Belum ada transaksi'}</span></div><div class="bar"><span style="width:${percent}%"></span></div><div class="legend"><span>● Terbayar <b>${rupiah(received)}</b></span><span>○ Sisa <b>${rupiah(total)}</b></span></div></div></div></div>`}
if(page==='dashboard')html+=debtChart()+'</div>';
if(page==='customers'){html+=`<div class="panel"><div class="panel-head"><div><h2>Daftar langganan</h2><p>${db.customers.length} langganan</p></div></div>${toolbar(false)}${customerDates()}<div id="rows"></div></div>`}else if(page==='payments'){html+=`<div class="panel"><div class="panel-head"><div><h2>Pembayaran masuk</h2></div></div>${toolbar(false)}${customerDates()}<div id="rows"></div></div>`}else html+=`<div class="panel"><div class="panel-head"><div><h2>${page==='dashboard'?'Pantauan piutang':'Semua tagihan'}</h2></div><button class="text-button" data-action="export">↓ Ekspor CSV</button></div>${toolbar(true)}<div id="rows"></div></div>`;$('#view').innerHTML=html;bindDebtChart();renderRows();bindCustomerDates();$('#search').value=query;$('#search-button').onclick=()=>{query=$('#search').value;renderRows()};$('#search').onkeydown=e=>{if(e.key==='Enter'){query=e.target.value;renderRows()}};if($('#filter')){$('#filter').value=filter;$('#filter').onchange=e=>{filter=e.target.value;renderRows()}}}
function toolbar(withFilter){return `<div class="table-toolbar"><input id="search" aria-label="Cari pembeli atau catatan" placeholder="Cari nama, ID, kota atau catatan…"><button id="search-button" class="primary">Cari</button>${withFilter?'<select id="filter" aria-label="Filter status"><option value="all">Semua status</option><option value="open">Belum lunas</option><option value="late">Terlambat</option>'+(page==='dashboard'?'':'<option value="paid">Lunas</option>')+'</select>':''}</div>`}
function renderRows(){const q=query.toLowerCase();let rows=[],head=[];if(page==='customers'){head=['ID','NAMA','KOTA','TEMPO','LIMIT UTANG','TOTAL TRANSAKSI','UTANG AKTIF','KESEHATAN KREDITUR',''];rows=db.customers.filter(c=>(c.name+' '+c.phone+' '+c.address+' '+(c.city||'')+' '+(c.registered_id||'')).toLowerCase().includes(q)).map(c=>{const transactions=transactionSummary(c.id);return `<td>${esc(c.registered_id||'—')}</td><td>${person(c)}</td><td>${esc(c.city||'Belum diisi')}</td><td>${terms(c)}</td><td>${c.credit_limit==null?'Belum diatur':rupiah(c.credit_limit)}</td><td><b>${rupiah(transactions.total)}</b><small>${transactions.count} transaksi${transactionFrom||transactionTo?' dalam periode':' sepanjang waktu'}</small></td><td><b>${rupiah(outstanding(c.id))}</b></td><td><span class="credit-health health-${({'Sangat baik':'excellent','Baik':'good','Tidak baik':'poor','Butuh perhatian':'attention'})[c.credit_health]||'unset'}">${esc(c.credit_health||'Belum dinilai')}</span></td><td><button class="text-button" data-action="edit" data-id="${c.id}">Edit langganan</button></td>`})}else if(page==='payments'){head=['TANGGAL PEMBAYARAN','NAMA LANGGANAN','JUMLAH DIBAYAR','METODE','CATATAN','RIWAYAT TAGIHAN'];rows=[...db.payments].sort((a,b)=>b.date.localeCompare(a.date)).filter(p=>{const d=db.debts.find(d=>d.id===p.debt_id);return (!transactionFrom||p.date>=transactionFrom)&&(!transactionTo||p.date<=transactionTo)&&(customer(d.customer_id).name+' '+p.note+' '+p.date+' '+date(p.date)).toLowerCase().includes(q)}).map(p=>{const d=db.debts.find(d=>d.id===p.debt_id);return `<td><b>${date(p.date)}</b></td><td>${person(customer(d.customer_id))}</td><td><b>${rupiah(p.amount)}</b></td><td>${esc(p.method)}</td><td>${esc(p.note||'—')}</td><td><button class="text-button" data-action="detail" data-id="${d.id}">Lihat riwayat</button></td>`})}else{head=['PEMBELI','SISA TAGIHAN','JATUH TEMPO','STATUS','TINDAKAN'];rows=[...db.debts].sort((a,b)=>a.due_date.localeCompare(b.due_date)).filter(d=>(page!=='dashboard'||balance(d)>0)&&(customer(d.customer_id).name+' '+d.note).toLowerCase().includes(q)&&(filter==='all'||status(d)===filter)).map(d=>`<td>${person(customer(d.customer_id))}<small>${esc(d.note)}</small></td><td><b>${rupiah(balance(d))}</b><small>dari ${rupiah(d.amount)}</small></td><td>${date(d.due_date)}</td><td><span class="badge ${status(d)}">${statusLabel[status(d)]}</span></td><td><button class="text-button" data-action="detail" data-id="${d.id}">Lihat detail ↗</button></td>`)}$('#rows').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r}</tr>`).join('')}</tbody></table></div><div class="table-foot">Menampilkan ${rows.length} ${page==='customers'?'pembeli':page==='payments'?'pembayaran':'tagihan'}</div>`:blank(query||filter!=='all'?'Tidak ada hasil yang cocok':page==='customers'?'Belum ada langganan':page==='payments'?'Belum ada pembayaran':'Tidak ada tagihan',query?'Coba kata pencarian lainnya.':'',query||page==='payments'?null:'customer','Tambah langganan')}
const field=(name,label,type='text',value='',extra='')=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
function openForm(kind,id){$('#error').textContent='';$('#form button[type="submit"]').style.display='';const c=id?customer(id):null;let fields='';if(kind==='customer'){ $('#modal-title').textContent=c?'Edit langganan':'Tambah langganan';fields=field('registered_id','ID terdaftar','text',c?.registered_id||'','maxlength="100" placeholder="Contoh: MJ-001"')+field('name','Nama langganan *','text',c?.name||'','required maxlength="100"')+'<label for="f-credit_health">Kesehatan kreditur</label><select id="f-credit_health" name="credit_health"><option value="">Belum dinilai</option>'+['Sangat baik','Baik','Tidak baik','Butuh perhatian'].map(value=>`<option value="${value}" ${c?.credit_health===value?'selected':''}>${value}</option>`).join('')+'</select>'+field('city','Kota *','text',c?.city||'','required maxlength="100"')+'<label for="f-payment_type">Ketentuan pembayaran *</label><select name="payment_type" id="f-payment_type"><option value="credit" '+(c?.payment_type!=='cash'?'selected':'')+'>Tempo</option><option value="cash" '+(c?.payment_type==='cash'?'selected':'')+'>Bayar di tempat</option></select>'+field('term_days','Lama tempo (hari) *','number',c?.term_days||30,'required min="1" max="3650" step="1"')+field('credit_limit','Limit utang (Rp) *','number',c?.credit_limit??'','required min="0" max="1000000000000" step="1"')+'<p class="note">Tanggal dan jumlah jatuh tempo dihitung dari tagihan belum lunas paling awal. Tagihan pada tanggal yang sama dijumlahkan.</p>'+field('phone','Nomor telepon / WhatsApp','tel',c?.phone||'','maxlength="25"')+field('address','Alamat','text',c?.address||'','maxlength="250"')}

if(kind==='debt'){if(!db.customers.length){toast('Tambahkan pembeli terlebih dahulu.');openForm('customer');return}$('#modal-title').textContent='Catat utang baru';fields='<label for="f-customer_id">Pembeli *</label><select id="f-customer_id" name="customer_id" required>'+db.customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')+'</select>'+field('amount','Total utang (Rp) *','number','','required min="1" max="1000000000000" step="1"')+field('date','Tanggal transaksi *','date',today(),'required')+field('due_date','Jatuh tempo *','date',today(),'required')+field('note','Keterangan barang / nomor nota','text','','maxlength="250"')}
if(kind==='payment'){const debts=db.debts.filter(d=>balance(d)>0);if(!debts.length){toast('Belum ada tagihan yang perlu dibayar.');return}$('#modal-title').textContent='Catat pembayaran';fields='<label for="f-debt_id">Tagihan *</label><select id="f-debt_id" name="debt_id">'+debts.map(d=>`<option value="${d.id}" ${d.id===id?'selected':''}>${esc(customer(d.customer_id).name)} · ${rupiah(balance(d))} · ${esc(d.note||date(d.date))}</option>`).join('')+'</select>'+field('amount','Jumlah pembayaran (Rp) *','number','','required min="1" step="1"')+field('date','Tanggal pembayaran *','date',today(),`required max="${today()}"`)+ '<label for="f-method">Metode pembayaran</label><select id="f-method" name="method"><option>Tunai</option><option>Transfer bank</option><option>QRIS</option></select>'+field('note','Catatan','text','','maxlength="250"')}
$('#fields').innerHTML=fields;
if(kind==='customer'){const sync=()=>{const cash=$('#f-payment_type').value==='cash';$('#f-term_days').disabled=cash;$('#f-term_days').required=!cash;$('#f-credit_limit').disabled=cash;$('#f-credit_limit').required=!cash};$('#f-payment_type').onchange=sync;sync()}
if(kind==='debt'){const sync=()=>{const buyer=customer($('#f-customer_id').value);if(buyer)$('#f-due_date').value=dueDate($('#f-date').value,buyer.term_days)};$('#f-customer_id').onchange=sync;$('#f-date').onchange=sync;sync()}
$('#form').onsubmit=async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target));const next=structuredClone(db);if(kind==='customer'){v.name=v.name.trim();if(!v.name)throw Error('Nama pembeli wajib diisi.');v.credit_health=v.credit_health||'';if(!['','Sangat baik','Baik','Tidak baik','Butuh perhatian'].includes(v.credit_health))throw Error('Status kesehatan kreditur tidak valid.');v.registered_id=(v.registered_id||'').trim();if(v.registered_id.length>100)throw Error('ID maksimal 100 karakter.');if(v.registered_id&&db.customers.some(x=>x.id!==id&&(x.registered_id||'').toLowerCase()===v.registered_id.toLowerCase()))throw Error('ID terdaftar sudah digunakan langganan lain.');v.city=(v.city||'').trim();if(!v.city)throw Error('Kota wajib diisi.');
if(!['cash','credit'].includes(v.payment_type))throw Error('Pilih ketentuan pembayaran.');
v.term_days=v.payment_type==='cash'?0:Number(v.term_days);v.credit_limit=v.payment_type==='cash'?0:Number(v.credit_limit);
if(v.payment_type==='credit'&&(!Number.isInteger(v.term_days)||v.term_days<1||v.term_days>3650))throw Error('Tempo harus 1–3650 hari.');
if(!Number.isSafeInteger(v.credit_limit)||v.credit_limit<0||v.credit_limit>1e12)throw Error('Limit utang tidak valid.');
if(c&&v.credit_limit<outstanding(c.id))throw Error('Limit tidak boleh lebih kecil dari sisa utang aktif. Lunasi dahulu atau gunakan limit lebih besar.');
if(c)Object.assign(next.customers.find(x=>x.id===id),v);else next.customers.push({...v,id:crypto.randomUUID()})}else{v.amount=Number(v.amount);if(!Number.isSafeInteger(v.amount)||v.amount<=0||v.amount>1e12)throw Error('Masukkan nominal rupiah yang valid.');if(v.date>today())throw Error('Tanggal transaksi tidak boleh di masa depan.');if(kind==='debt'){const buyer=customer(v.customer_id);if(!buyer)throw Error('Langganan tidak ditemukan.');if(buyer.payment_type==='cash')throw Error('Langganan ini bayar di tempat. Tidak dapat membuat utang.');if(buyer.credit_limit==null||!buyer.term_days)throw Error('Lengkapi tempo dan limit utang pada data langganan terlebih dahulu.');if(outstanding(buyer.id)+v.amount>buyer.credit_limit)throw Error('Total utang melebihi limit langganan. Sisa limit: '+rupiah(buyer.credit_limit-outstanding(buyer.id)));if(v.due_date<v.date)throw Error('Jatuh tempo tidak boleh sebelum tanggal transaksi.');next.debts.push({...v,id:crypto.randomUUID()})}else{const d=db.debts.find(d=>d.id===v.debt_id);if(v.amount>balance(d))throw Error('Pembayaran melebihi sisa utang.');if(v.date<d.date)throw Error('Pembayaran tidak boleh sebelum tanggal transaksi.');next.payments.push({...v,id:crypto.randomUUID()})}}await save(next);$('#modal').close();render();toast('Data berhasil disimpan.')}catch(err){$('#error').textContent=err.name==='QuotaExceededError'?'Penyimpanan penuh. Ekspor cadangan sebelum melanjutkan.':err.message}};$('#modal').showModal()}
function detail(id){const d=db.debts.find(x=>x.id===id);$('#modal-title').textContent='Detail tagihan';$('#error').textContent='';$('#form button[type="submit"]').style.display='none';$('#fields').innerHTML=`<div class="detail-summary"><h2>${esc(customer(d.customer_id).name)}</h2><p>${esc(d.note||'Tanpa keterangan')}</p><p>Transaksi ${date(d.date)} · Jatuh tempo ${date(d.due_date)}</p><h2 style="margin-top:15px">Sisa ${rupiah(balance(d))}</h2><p>Total awal ${rupiah(d.amount)}</p></div><h3>Riwayat pembayaran</h3>${db.payments.filter(p=>p.debt_id===id).sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<div class="history"><small>Tanggal pembayaran</small><div><b>${date(p.date)}</b> · ${rupiah(p.amount)}</div><p>${esc(p.method)} ${esc(p.note)}</p></div>`).join('')||'<p>Belum ada pembayaran.</p>'}${balance(d)>0?`<button class="primary" type="button" data-action="pay" data-id="${id}" style="margin-top:20px">＋ Catat pembayaran</button>`:'<p class="badge paid">Tagihan sudah lunas</p>'}`;$('#modal').showModal()}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(){const safe=v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Nama langganan','Kota','Ketentuan bayar','Limit utang','Tanggal transaksi','Tanggal jatuh tempo','Total','Terbayar','Jumlah jatuh tempo','Status','Catatan'],...db.debts.map(d=>[customer(d.customer_id).name,customer(d.customer_id).city||'',terms(customer(d.customer_id)),customer(d.customer_id).credit_limit??'',d.date,d.due_date,d.amount,paid(d.id),balance(d),statusLabel[status(d)],d.note])];download('piutang-maju-jaya.csv','\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='customer')openForm('customer');if(action==='edit')openForm('customer',id);if(action==='detail')detail(id);if(action==='pay'){$('#modal').close();openForm('payment',id)}if(action==='export')csv()});
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(page==='customers'||page==='payments')savedDateRanges[page]={from:transactionFrom,to:transactionTo,preset:datePreset};page=b.dataset.page;const range=savedDateRanges[page];transactionFrom=range?.from||'';transactionTo=range?.to||'';datePreset=range?.preset||'all';query='';filter='all';render()});$('#add').onclick=()=>page==='orders'?orderForm():openForm(page==='customers'?'customer':page==='payments'?'payment':'debt');$('#close').onclick=$('#cancel').onclick=()=>$('#modal').close();$('#backup').onclick=()=>download(`maju-jaya-cadangan-${today()}.json`,JSON.stringify(db,null,2),'application/json');$('#today').textContent=new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
